#!/usr/bin/env python3
"""
Round 141b (culprits), 2 October 2026. Needs round 140b.

Combine the ticked layers: crossings edged, the rest nearly hidden.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 141b (2 October)\n\nNeeds round 140b. No tiles patch. No app.js?v= bump.\n\n- Combine the ticked layers, made easier to read (asked 2 October: the\n  highlight and the fade were too alike):\n  - the veil is nearly opaque (COMBO_VEIL 0.94, was 0.82) and lies above every\n    layer of the rows taking part, points and lines included, so everything\n    that is not a crossing is almost gone;\n  - the crossings are edged in pale ice (#CFEAF4, layer combo-mask-edge) and\n    faintly tinted (combo-mask-glow);\n  - the combine has its own grid (comboGrid): smoothed once by one square, so\n    a layer counts in a 0.25-degree square when it lies within about 50 km\n    (was about 200 km, the density bands' smoothing): crossings are tighter.\n"]


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round141b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 140b" not in h.read_text(encoding="utf-8"):
        sys.exit("round141b: round 140b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round141b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round141b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round141b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ""

if __name__ == "__main__":
    main()
